package com.lexorion.payroll.service;

import com.lexorion.payroll.api.PayrollException;import com.lexorion.payroll.domain.*;import com.lexorion.payroll.repository.*;import java.math.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service public class PayRunTransactions{private static final BigDecimal ZERO=new BigDecimal("0.0000");private final PayrollWorkspaceScope scope;private final PayRunService service;private final PayRunRepository runs;private final PayRunEmployeeRepository employees;private final CalculationService calculations;public PayRunTransactions(PayrollWorkspaceScope s,PayRunService ps,PayRunRepository r,PayRunEmployeeRepository e,CalculationService c){scope=s;service=ps;runs=r;employees=e;calculations=c;}@Transactional(propagation=Propagation.REQUIRES_NEW)public void begin(String key){scope.locked();PayRun run=service.locked(key);PayRunService.requireStatus(run,PayRunStatus.DRAFT);if(employees.countByPayRunId(run.getId())==0)throw new PayrollException(409,"Empty Pay Run cannot be processed");run.setStatus(PayRunStatus.PROCESSING);runs.saveAndFlush(run);}@Transactional(propagation=Propagation.REQUIRES_NEW,isolation=Isolation.REPEATABLE_READ)public PayRun complete(String key){PayrollWorkspace workspace=scope.locked();PayRun run=service.locked(key);PayRunService.requireStatus(run,PayRunStatus.PROCESSING);List<PayRunEmployee>included=employees.findByPayRunIdOrderByEmployeeCodeAsc(run.getId());BigDecimal gross=ZERO,deductions=ZERO,net=ZERO;for(PayRunEmployee item:included){if(item.getPayrollEmployee().getStatus()!=PayrollStatus.ACTIVE)throw new PayrollException(409,"Pay Run contains an inactive payroll employee");Calculation calculation=calculations.calculateSnapshot(workspace,item.getEmployeeCode(),run.getCalculationDate());if(!run.getCurrency().equals(calculation.getCurrency()))throw new PayrollException(409,"Employee calculation currency does not match Pay Run currency");item.setCalculation(calculation);item.setGrossSnapshot(calculation.getGrossAmount());item.setDeductionSnapshot(calculation.getDeductionAmount());item.setNetSnapshot(calculation.getNetAmount());item.setCurrency(calculation.getCurrency());employees.save(item);gross=gross.add(calculation.getGrossAmount());deductions=deductions.add(calculation.getDeductionAmount());net=net.add(calculation.getNetAmount());}gross=money(gross);deductions=money(deductions);net=money(net);if(net.compareTo(gross.subtract(deductions))!=0)throw new PayrollException(409,"Pay Run totals are inconsistent");run.setGrossTotal(gross);run.setDeductionTotal(deductions);run.setNetTotal(net);run.setStatus(PayRunStatus.CALCULATED);return runs.saveAndFlush(run);}@Transactional(propagation=Propagation.REQUIRES_NEW)public void fail(String key){scope.locked();PayRun run=service.locked(key);if(run.getStatus()==PayRunStatus.PROCESSING){run.setStatus(PayRunStatus.FAILED);runs.saveAndFlush(run);}}private BigDecimal money(BigDecimal value){BigDecimal result=value.setScale(4,RoundingMode.HALF_UP);if(result.precision()-result.scale()>15)throw new PayrollException(409,"Pay Run total exceeds supported precision");return result;}}
